import { describe, expect, it } from "vitest";

/**
 * profile-todo-cleanup — AC-3: `docs/product/ACTION-APP-CONTRACT.md` is
 * formatted with the project's Prettier configuration, so
 * `npx prettier --check` on it exits 0.
 */

describe("ACTION-APP-CONTRACT.md formatting (profile-todo-cleanup)", () => {
  it("AC-3: npx prettier --check docs/product/ACTION-APP-CONTRACT.md exits with status 0", async () => {
    const { spawnSync } = await import("node:child_process");

    const run = spawnSync(
      "npx",
      ["prettier", "--check", "docs/product/ACTION-APP-CONTRACT.md"],
      {
        cwd: process.cwd(),
        encoding: "utf8",
        timeout: 120_000,
      },
    );
    const output = `${run.stdout ?? ""}\n${run.stderr ?? ""}`;

    expect(run.error, "npx prettier started").toBeUndefined();
    expect(run.status, output).toBe(0);
  }, 150_000);
});

import { describe, expect, it } from "vitest";

/**
 * profile-todo-cleanup — AC-2: the doc comment directly above
 * `export async function getProfileData` states that the profile is per
 * person and takes no organization id, and carries no TODO.
 */

describe("getProfileData's doc comment (profile-todo-cleanup)", () => {
  it('AC-2: the doc comment directly above getProfileData contains "per person" and "organization id" and no "TODO"', async () => {
    const { readFile } = await import("node:fs/promises");
    const { resolve } = await import("node:path");

    const source = await readFile(
      resolve(process.cwd(), "features/profile/services/get-profile.ts"),
      "utf8",
    );

    const declaration =
      "export async function getProfileData(userId: string): Promise<ProfileData>";
    const declarationIndex = source.indexOf(declaration);
    expect(declarationIndex, "getProfileData is declared").toBeGreaterThan(-1);

    const before = source.slice(0, declarationIndex);
    const commentEnd = before.lastIndexOf("*/");
    expect(commentEnd, "a doc comment precedes getProfileData").toBeGreaterThan(
      -1,
    );
    expect(
      before.slice(commentEnd + 2).trim(),
      "only whitespace between the doc comment and getProfileData",
    ).toBe("");

    const commentStart = before.lastIndexOf("/**", commentEnd);
    expect(commentStart, "the doc comment opens with /**").toBeGreaterThan(-1);
    const comment = before.slice(commentStart, commentEnd + 2);

    expect(comment).toContain("per person");
    expect(comment).toContain("organization id");
    expect(comment).not.toContain("TODO");
  });
});

import { describe, expect, it } from "vitest";

/**
 * profile-todo-cleanup — AC-1: no file under `features/profile/` mentions
 * "multi-workspace support", and no line there carries a TODO about an
 * organizationId parameter. This test lives outside `features/profile/` so
 * its own search strings are never part of the searched tree.
 */

describe("features/profile carries no stale workspace TODO (profile-todo-cleanup)", () => {
  it('AC-1: no file under features/profile/ contains "multi-workspace support" or a TODO mentioning organizationId', async () => {
    const { readdir, readFile } = await import("node:fs/promises");
    const { join, relative, resolve } = await import("node:path");

    const root = resolve(process.cwd(), "features/profile");

    async function walk(dir: string): Promise<string[]> {
      const entries = await readdir(dir, { withFileTypes: true });
      const files: string[] = [];
      for (const entry of entries) {
        const path = join(dir, entry.name);
        if (entry.isDirectory()) {
          files.push(...(await walk(path)));
        } else if (entry.isFile()) {
          files.push(path);
        }
      }
      return files;
    }

    const files = await walk(root);
    expect(files.length, "features/profile/ holds files").toBeGreaterThan(0);

    const workspaceSupportHits: string[] = [];
    const todoOrganizationIdHits: string[] = [];
    for (const file of files) {
      const text = await readFile(file, "utf8");
      const name = relative(process.cwd(), file);
      if (text.includes("multi-workspace support")) {
        workspaceSupportHits.push(name);
      }
      text.split("\n").forEach((line, index) => {
        const lower = line.toLowerCase();
        if (lower.includes("todo") && lower.includes("organizationid")) {
          todoOrganizationIdHits.push(`${name}:${index + 1}`);
        }
      });
    }

    expect(workspaceSupportHits).toEqual([]);
    expect(todoOrganizationIdHits).toEqual([]);
  });
});

